-- Elev8: completa a operação do pós-venda e cria o próximo passo após reunião realizada.

on conflict (id) do update set name=excluded.name,is_active=true,settings=excluded.settings,updated_at=now();

on conflict (id) do update set config=excluded.config,next_block_id=excluded.next_block_id,updated_at=now();

on conflict (id) do update set action=excluded.action,enabled=true,updated_at=now();
